// Category — extend existing class (even Foundation classes)
@interface NSString (Utilities)
- (BOOL)isPalindrome;
- (NSInteger)wordCount;
@end

@implementation NSString (Utilities)
- (BOOL)isPalindrome {
    NSString *lower = [self lowercaseString];
    NSString *rev = [NSString stringWithString:
        [[self componentsSeparatedByString:@""] reverseObjectEnumerator].allObjects
        componentsJoinedByString:@""];
    return [lower isEqualToString:rev];
}
- (NSInteger)wordCount {
    return [[self componentsSeparatedByCharactersInSet:
        [NSCharacterSet whitespaceAndNewlineCharacterSet]] count];
}
@end

// Usage
NSLog(@"%@", [@"racecar" isPalindrome] ? @"palindrome" : @"not");
