// ARC (Automatic Reference Counting) — modern Objective-C
// Property memory semantics:
@property (nonatomic, strong) NSObject *obj;    // strong: retains object
@property (nonatomic, weak)   id<NSObject> delegate;  // weak: doesn't retain
@property (nonatomic, copy)   NSString *name;   // copy: defensive for mutables
@property (nonatomic, assign) NSInteger count;  // assign: for primitives

// Avoid retain cycles with blocks
- (void)doWorkWithCompletion:(void(^)(NSString *))completion {
    __weak typeof(self) weakSelf = self;    // weak reference
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        __strong typeof(weakSelf) strongSelf = weakSelf;
        if (!strongSelf) return;
        NSString *result = [strongSelf computeResult];
        dispatch_async(dispatch_get_main_queue(), ^{
            completion(result);
        });
    });
}

// Autorelease pool for large loops
for (int i = 0; i < 10000; i++) {
    @autoreleasepool {
        NSString *s = [NSString stringWithFormat:@"item %d", i];
        // s autoreleased at end of pool iteration
    }
}
