    });
});

// Delayed execution
dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 2 * NSEC_PER_SEC), main_q, ^{
    NSLog(@"After 2 seconds");
});

// dispatch_once — thread-safe singleton
